  `nro` INT(11) NOT NULL,
  `descrip` VARCHAR(60) NULL,
  `estado` ENUM('tramite', 'aceptado', 'rechazado', 'solicitado', 'rec_parc', 'rec_total', 'ent_parc', 'ent_total') NOT NULL DEFAULT 'tramite' COMMENT 'tramite: cuando se inicia, aceptado: vºbº de admon y responsable, rechazado: ha sido rechazado por admon o responsable, solicitado: pedido por el almacén, rec_parc: recibido parcialmente en el almacén, rec_total: recibido en su totalidad en el almacé' /* comment truncated */ /*n, ent_parc: entregado parcialmente a su peticionario, ent_total: entregado totalmente a su peticionario*/,
  `razonrechazo` VARCHAR(45) NULL COMMENT 'refleja rechazo dependiendo del paso de trámite en el que esté',
  `pasotramite` ENUM('admon', 'responsable', 'almacen', 'ninguno') NOT NULL DEFAULT 'ninguno' COMMENT 'admon, responsable, almacen, ninguno',
  `fechatramite` DATETIME NOT NULL,
  `fechaaceptado` DATETIME NULL,
  `fechasolicitado` DATETIME NULL,
  `fecharecparc` DATETIME NULL,
  `fecharectotal` DATETIME NULL,
  `fechaentparc` DATETIME NULL,
  `fechaenttotal` DATETIME NULL,
  `fecharechazado` DATETIME NULL,
  PRIMARY KEY (`id`))
ENGINE = MyISAM;


-- -----------------------------------------------------
-- Table `almacenarticulospedidos`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `almacenarticulospedidos` (
