  `estadoadmonalmacen` ENUM('tramite', 'aceptado', 'reparo') NOT NULL DEFAULT 'tramite' COMMENT 'tramite: recibido y en trámite, aceptado: correcto para pedir, reparo: no pedir por alguna razón',
  `estadoresponsable` ENUM('tramite', 'aceptado', 'rechazado') NOT NULL DEFAULT 'tramite' COMMENT 'tramite: recibido y en trámite, aceptado: correcto para pedir, rechazado: no pedir por alguna razón',
  `estadoalmacen` ENUM('tramite', 'rechazado', 'solicitado', 'rec_parc', 'rec_total', 'ent_parc', 'ent_total') NOT NULL DEFAULT 'tramite' COMMENT 'tramite: recibido y en trámite, rechazado: no pedido por alguna razón, solicitado: pedido a proveedor, rec_parc: recibido parcialmente, rec_total: recibido totalmente, ent_parc: entregado parcialmente, ent_total: entregado totalmente',
  `razonreparoadmonalmacen` VARCHAR(45) NULL,
